MODULE_SOURCE='\nfrom dataclasses import dataclass, is_dataclass\nfrom pathlib import Path\nfrom datetime import datetime, timezone\nimport importlib\nimport inspect\nimport json\n\nfrom qseries_v2.oracle_source_network.runtime.exact_sports_runtime_callable_bindings import load_bindings\n\nADMITTED = ("NFL","NCAAF","NBA","NHL","MLS","EPL")\n\n@dataclass(frozen=True)\nclass DirectCycleResult:\n    league: str\n    callables_attempted: tuple\n    canonical_events: tuple\n    event_count: int\n    acquisition_type: str\n    extractor_input_type: str\n    execution_authority: bool = False\n\ndef _is_event_object(x):\n    if x is None or isinstance(x, (str, bytes, bytearray, dict, list, tuple)):\n        return False\n    names = set(dir(x))\n    has_id = bool({"provider_event_id","canonical_event_id","event_id"} & names)\n    has_home = bool({"home","home_team","home_name"} & names)\n    has_away = bool({"away","away_team","away_name"} & names)\n    return has_id and has_home and has_away\n\ndef _direct_event_objects(value):\n    if _is_event_object(value):\n        return (value,)\n    if isinstance(value, (list,tuple)):\n        found=[]\n        for item in value:\n            found.extend(_direct_event_objects(item))\n        return tuple(found)\n    if isinstance(value, dict):\n        found=[]\n        for v in value.values():\n            found.extend(_direct_event_objects(v))\n        return tuple(found)\n    for attr in ("events","games","fixtures","matches","rows","data","result"):\n        if hasattr(value,attr):\n            found=list(_direct_event_objects(getattr(value,attr)))\n            if found:\n                return tuple(found)\n    return ()\n\ndef _all_binary_text_candidates(value, path="$"):\n    out=[]\n    if isinstance(value, (bytes, bytearray)):\n        out.append((path, bytes(value)))\n    elif isinstance(value, str):\n        out.append((path, value))\n    elif isinstance(value, dict):\n        for k,v in value.items():\n            out.extend(_all_binary_text_candidates(v, f"{path}.{k}"))\n    elif isinstance(value, (list,tuple)):\n        for i,v in enumerate(value):\n            out.extend(_all_binary_text_candidates(v, f"{path}[{i}]"))\n    else:\n        for attr in ("body","raw","html","text","content","payload","data"):\n            if hasattr(value,attr):\n                out.extend(_all_binary_text_candidates(getattr(value,attr), f"{path}.{attr}"))\n    return out\n\ndef _extractor_payload(value):\n    if isinstance(value,(str,bytes,bytearray)):\n        return value, "$"\n\n    candidates=_all_binary_text_candidates(value)\n    if not candidates:\n        raise RuntimeError(\n            "acquisition result contains no string/bytes payload suitable for exact extractor; "\n            f"type={type(value).__name__}"\n        )\n\n    # Prefer explicit transport-body names when present; otherwise choose the largest\n    # physical payload. This uses observed runtime structure, not a source-specific guessed key.\n    preferred=[]\n    for p,v in candidates:\n        low=p.lower()\n        if any(token in low for token in (".body",".raw",".html",".text",".content",".payload")):\n            preferred.append((p,v))\n    pool=preferred or candidates\n    pool.sort(key=lambda pv: len(pv[1]), reverse=True)\n    return pool[0][1], pool[0][0]\n\ndef _call(fn, required, optional, payload, league, timeout):\n    kwargs={}\n    if "timeout" in optional:\n        kwargs["timeout"]=timeout\n    if "observed_at" in optional:\n        kwargs["observed_at"]=datetime.now(timezone.utc).isoformat()\n\n    if not required:\n        return fn(**kwargs)\n\n    args=[]\n    for name in required:\n        if name in ("body","raw","payload","html","text","data","document"):\n            args.append(payload)\n        elif name=="league":\n            args.append(league)\n        elif name=="provider":\n            args.append("nba_official" if league=="NBA" else league.lower()+"_official")\n        else:\n            raise RuntimeError(f"unsupported required argument {name!r} for {fn.__module__}:{fn.__name__}")\n    return fn(*args,**kwargs)\n\ndef _mapping_candidates(value):\n    found=[]\n    if isinstance(value,dict):\n        keys={str(k).lower() for k in value}\n        homeish=any(k in keys for k in ("home","home_team","hometeam","home_team_name","team_h","h"))\n        awayish=any(k in keys for k in ("away","away_team","awayteam","away_team_name","team_a","a"))\n        idish=any(k in keys for k in ("id","gameid","game_id","eventid","event_id","match_id","provider_event_id"))\n        if homeish and awayish and idish:\n            found.append(value)\n        for v in value.values():\n            found.extend(_mapping_candidates(v))\n    elif isinstance(value,(list,tuple)):\n        for v in value:\n            found.extend(_mapping_candidates(v))\n    return found\n\ndef _first(mapping, names):\n    lower={str(k).lower():v for k,v in mapping.items()}\n    for name in names:\n        if name.lower() in lower and lower[name.lower()] not in (None,""):\n            return lower[name.lower()]\n    return None\n\ndef _team_name(v):\n    if isinstance(v,dict):\n        return (\n            _first(v,("name","fullName","full_name","teamName","team_name","abbrev","abbreviation","shortName"))\n            or str(v)\n        )\n    return v\n\ndef _canonical_class():\n    mod=importlib.import_module("qseries_v2.oracle_source_network.canonical.sports_event_v2")\n    cls=getattr(mod,"CanonicalSportsEvent",None)\n    if cls is None:\n        raise RuntimeError("CanonicalSportsEvent missing from sports_event_v2")\n    return cls\n\ndef _mapping_to_canonical(league, mapping):\n    cls=_canonical_class()\n    sig=inspect.signature(cls)\n\n    home=_team_name(_first(mapping,("home","home_team","homeTeam","home_team_name","team_h")))\n    away=_team_name(_first(mapping,("away","away_team","awayTeam","away_team_name","team_a")))\n    eid=_first(mapping,("provider_event_id","event_id","eventId","game_id","gameId","match_id","id"))\n    start=_first(mapping,(\n        "scheduled_start","start","start_time","startTime","startTimeUTC",\n        "gameDate","match_scheduled","planned_kickoff_time","date"\n    ))\n    status=_first(mapping,("status","gameState","match_status","state"))\n    season=_first(mapping,("season","season_id","seasonId"))\n    observed=datetime.now(timezone.utc).isoformat()\n\n    values={\n        "league":league,\n        "season":str(season or ""),\n        "provider":league.lower()+"_official",\n        "home":str(home or ""),\n        "away":str(away or ""),\n        "home_team":str(home or ""),\n        "away_team":str(away or ""),\n        "scheduled_start":str(start or observed),\n        "source_observed_at":observed,\n        "source_authority":"official",\n        "provider_event_id":str(eid or ""),\n        "event_discriminator":"",\n        "status":str(status or ""),\n        "scores":None,\n        "schedule_revision":None,\n        "read_only":True,\n        "execution_authority":False,\n    }\n\n    kwargs={}\n    for name,p in sig.parameters.items():\n        if name=="self":\n            continue\n        if name in values:\n            kwargs[name]=values[name]\n        elif p.default is inspect._empty:\n            raise RuntimeError(\n                f"cannot safely construct CanonicalSportsEvent from mapping; "\n                f"required field {name!r} has no exact runtime mapping"\n            )\n\n    event=cls(**kwargs)\n    if not _is_event_object(event):\n        raise RuntimeError("constructed CanonicalSportsEvent failed event-shape validation")\n    return event\n\ndef _canonicalize_acquisition_only(league, value):\n    direct=_direct_event_objects(value)\n    if direct:\n        return direct\n    mappings=_mapping_candidates(value)\n    if not mappings:\n        return ()\n    events=[]\n    seen=set()\n    for m in mappings:\n        try:\n            ev=_mapping_to_canonical(league,m)\n        except Exception:\n            continue\n        key=str(getattr(ev,"provider_event_id","")) or repr(ev)\n        if key in seen:\n            continue\n        seen.add(key)\n        events.append(ev)\n    return tuple(events)\n\ndef acquire_canonical_events(league, root=None, timeout=12):\n    if league not in ADMITTED:\n        raise RuntimeError(f"league not admitted to direct production cycle: {league}")\n\n    data=load_bindings(root=root)\n    rows=[r for r in data["bindings"] if r["league"]==league]\n\n    acquisition=[r for r in rows if r["function"].startswith("acquire_")]\n    extractors=[r for r in rows if not r["function"].startswith("acquire_")]\n\n    if len(acquisition)!=1:\n        raise RuntimeError(f"{league} expected exactly one admitted acquisition callable, found {len(acquisition)}")\n\n    acq=acquisition[0]\n    fn=getattr(importlib.import_module(acq["module"]),acq["function"])\n    attempted=[acq["module"]+":"+acq["function"]]\n    raw=_call(fn,tuple(acq["required"]),tuple(acq["optional"]),None,league,timeout)\n\n    direct=_direct_event_objects(raw)\n    if direct:\n        return DirectCycleResult(\n            league,tuple(attempted),tuple(direct),len(direct),\n            type(raw).__name__,"DIRECT_EVENT_OBJECT"\n        )\n\n    extractor_input_type="NONE"\n\n    if extractors:\n        payload,payload_path=_extractor_payload(raw)\n        extractor_input_type=f"{type(payload).__name__}@{payload_path}"\n\n        errors=[]\n        for ext in extractors:\n            efn=getattr(importlib.import_module(ext["module"]),ext["function"])\n            attempted.append(ext["module"]+":"+ext["function"])\n            try:\n                value=_call(\n                    efn,\n                    tuple(ext["required"]),\n                    tuple(ext["optional"]),\n                    payload,\n                    league,\n                    timeout,\n                )\n            except Exception as exc:\n                errors.append(f"{ext[\'function\']}:{type(exc).__name__}:{exc}")\n                continue\n\n            events=_direct_event_objects(value)\n            if events:\n                return DirectCycleResult(\n                    league,tuple(attempted),tuple(events),len(events),\n                    type(raw).__name__,extractor_input_type\n                )\n\n        raise RuntimeError(\n            f"{league} acquisition succeeded but exact extractor chain produced zero canonical events; "\n            f"acquisition_type={type(raw).__name__}; extractor_input={extractor_input_type}; "\n            f"attempted={attempted}; errors={errors}"\n        )\n\n    # NHL/MLS/EPL currently have acquisition-only frozen interfaces.\n    events=_canonicalize_acquisition_only(league,raw)\n    if events:\n        return DirectCycleResult(\n            league,tuple(attempted),tuple(events),len(events),\n            type(raw).__name__,"ACQUISITION_ONLY_DYNAMIC_CANONICALIZATION"\n        )\n\n    raise RuntimeError(\n        f"{league} acquisition succeeded but returned no directly canonicalizable events; "\n        f"acquisition_type={type(raw).__name__}; attempted={attempted}. "\n        "No hidden certification wrapper used."\n    )\n'
TEST_SOURCE='\nfrom pathlib import Path\nimport json\nfrom qseries_v2.oracle_source_network.runtime.direct_canonical_sports_cycle import acquire_canonical_events\n\nroot=Path.cwd()\nrows=[]\n\nfor league in ("NFL","NCAAF","NBA","NHL","MLS","EPL"):\n    r=acquire_canonical_events(league,root=root,timeout=12)\n    print(\n        f"[DIRECT] {league} events={r.event_count} "\n        f"acquisition_type={r.acquisition_type} extractor_input={r.extractor_input_type}"\n    )\n    for c in r.callables_attempted:\n        print("  [CALL]",c)\n\n    assert r.event_count > 0\n    assert r.execution_authority is False\n\n    rows.append({\n        "league":league,\n        "event_count":r.event_count,\n        "callables":list(r.callables_attempted),\n        "acquisition_type":r.acquisition_type,\n        "extractor_input_type":r.extractor_input_type,\n    })\n\nreport=root/"qseries_v2/oracle_source_network/state/osn077_direct_canonical_cycle.json"\nreport.write_text(\n    json.dumps({"rows":rows,"execution_authority":False},indent=2),\n    encoding="utf-8",\n)\n\nprint("[REPORT]",report)\nprint("[PASS] acquisition return shapes physically normalized before exact extraction")\nprint("[PASS] six admitted leagues produced canonical events through direct Python callables")\nprint("[PASS] subprocess certification wrappers are not used by production cycle")\nprint("[PASS] held/blocked leagues excluded")\nprint("[PASS] OSN-077 return-shape rebuild certified")\n'

